// Verify the recorded C1 -> fixture release -> C2 -> box lifecycle for each material identity.
// This file reads evidence only; it does not drive the controller or modify the scene.
using System;using System.IO;using System.Linq;using System.Text;using System.Text.Json;using System.Collections.Generic;using System.Globalization;using System.Security.Cryptography;
namespace MA6212.Commissioning {
 public sealed class Demo012Case {public int Cycle,Slot;public double Dx,Dy;public bool Clear;}
 public sealed class Demo012Material {public string Id;public int Sequence,Stage,Slot=-1;public double[] World;}
 public sealed class Demo012LedgerContext {public string ActorRun,LogDirectory,InitialId,LayoutHash,PolicyHash,PriorEvidenceSha256,PublicMeshFingerprint;public HashSet<string> Prior;public Demo012Case[] Cases;public double[] Source,Fixture,Ready;public double[][] Slots;public double PlaceMm,PlaceDeg,WorldMm,WorldDeg,ReadyMm,ReadyDeg;}
 public sealed class Demo012LedgerResult {public Dictionary<string,Demo012Material> Materials=new Dictionary<string,Demo012Material>();public List<string> Accepted=new List<string>();public List<string> ClearProofPaths=new List<string>();public int Feeds,FixtureReleases,C1,C2,Clears,Archived,CompleteRecords,TrailingBytes;public string ActorCaptureSHA256;public double[] ReadyReadySeconds;public double SumReadyReadySeconds;}
 public static class Demo012Ledger {
  static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
  public static string Id(string value){if(!Guid.TryParse(value,out var id)||id==Guid.Empty)throw new InvalidDataException("Actual nonempty material GUID required");return id.ToString("D");}
  public static byte[] Read(string path){if(!Path.IsPathRooted(path??""))throw new InvalidDataException("Absolute evidence path required");using var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);using var m=new MemoryStream();f.CopyTo(m);return m.ToArray();}
  public static string Hash(byte[] bytes)=>Convert.ToHexString(SHA256.HashData(bytes));
  public static double[] Matrix(JsonElement value){var a=value.EnumerateArray().Select(x=>x.GetDouble()).ToArray();if(a.Length!=16||a.Any(x=>!double.IsFinite(x))||Math.Abs(a[3])+Math.Abs(a[7])+Math.Abs(a[11])+Math.Abs(a[15]-1)>1e-8)throw new InvalidDataException("Finite homogeneous16 matrix required");return a;}
  public static (double Mm,double Deg) Error(double[] a,double[] b){if(a.Length!=16||b.Length!=16||a.Concat(b).Any(x=>!double.IsFinite(x)))throw new InvalidDataException("Finite16 matrices required");double mm=1000*Math.Sqrt(new[]{12,13,14}.Sum(i=>(a[i]-b[i])*(a[i]-b[i]))),trace=new[]{0,1,2,4,5,6,8,9,10}.Sum(i=>a[i]*b[i]);return(mm,Math.Acos(Math.Clamp((trace-1)/2,-1,1))*180/Math.PI);}
  static void At(double[] a,double[] b,double mm,double deg,string label){var e=Error(a,b);if(e.Mm>mm||e.Deg>deg)throw new InvalidDataException(label+" pose outside exact frozen tolerance: "+e);}
  static double[] Spawn(Demo012LedgerContext c,int sequence){var a=(double[])c.Source.Clone();a[12]+=c.Cases[sequence-1].Dx/1000;a[13]+=c.Cases[sequence-1].Dy/1000;return a;}
  static JsonElement Part(JsonElement row,string id,string phase,bool attached,int? slot=null){var matches=row.GetProperty("parts").EnumerateArray().Where(p=>Id(p.GetProperty("id").GetString())==id).ToArray();if(matches.Length!=1||matches[0].GetProperty("Phase").GetString()!=phase||matches[0].GetProperty("attachedToTool").GetBoolean()!=attached||slot.HasValue&&matches[0].GetProperty("Slot").GetInt32()!=slot.Value)throw new InvalidDataException("Actual unique part phase/attachment/slot record mismatch");return matches[0];}
  static Demo012Material Material(Demo012LedgerResult l,string id,int stage){if(!l.Materials.TryGetValue(id,out var m)||m.Stage!=stage)throw new InvalidDataException("Material lifecycle/order mismatch: "+id);return m;}
  static void NewMaterial(Demo012LedgerResult l,Demo012LedgerContext c,string id,int sequence,double[] world){if(sequence!=l.Materials.Count+1||sequence<1||sequence>20||c.Prior.Contains(id)||l.Materials.ContainsKey(id))throw new InvalidDataException("Fresh unique ordered material ID required");At(world,Spawn(c,sequence),c.PlaceMm,c.PlaceDeg,"Measured recorded source offset");l.Materials.Add(id,new Demo012Material{Id=id,Sequence=sequence,Stage=0,World=world});}
  static bool SameSet(IEnumerable<string> a,IEnumerable<string> b){var aa=a.ToArray();var bb=b.ToArray();return aa.Length==aa.Distinct().Count()&&bb.Length==bb.Distinct().Count()&&aa.Length==bb.Length&&aa.ToHashSet().SetEquals(bb);}
  public static Demo012LedgerResult Verify(string actorPath,string csvPath,string capturePath,Demo012LedgerContext c,int run){
   var l=new Demo012LedgerResult();byte[] bytes=Read(actorPath);l.ActorCaptureSHA256=Hash(bytes);int end=Array.LastIndexOf(bytes,(byte)10);if(end<0)throw new InvalidDataException("No complete actor record");l.TrailingBytes=bytes.Length-end-1;
   using(var f=new FileStream(capturePath,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){f.Write(bytes);f.Flush(true);} // exact captured bytes, explicitly not a sealed LF-only prior log
   using var memory=new MemoryStream(bytes,0,end+1,false);using var reader=new StreamReader(memory,new UTF8Encoding(false,true));bool began=false;string template=null;List<string> pendingClear=null;int[] sizes={0,6,4,6},beforeCounts={0,6,10,16};double lastTime=-1;
   string line;while((line=reader.ReadLine())!=null){if(line.Length==0)throw new InvalidDataException("Unexpected empty actor record");using var doc=JsonDocument.Parse(line);var row=doc.RootElement;string kind=row.GetProperty("kind").GetString();double time=row.GetProperty("virtualTimeMs").GetDouble();if(!double.IsFinite(time)||time<lastTime)throw new InvalidDataException("Actor virtual time rewound");lastTime=time;l.CompleteRecords++;var detail=row.GetProperty("detail");
    if(kind=="fault")throw new InvalidDataException("Actual actor fault retained; no batch acceptance");
    if(kind=="simulation_start"){if(began||l.Materials.Count!=0||detail.GetProperty("layout").GetString()!=c.LayoutHash||detail.GetProperty("policy").GetString()!=c.PolicyHash||detail.GetProperty("priorAcceptedEvidenceSha256").GetString()!=c.PriorEvidenceSha256)throw new InvalidDataException("Exact own fresh actor start required");began=true;template=Id(detail.GetProperty("nonactiveTemplateId").GetString());var ids=detail.GetProperty("priorAcceptedPartIds").EnumerateArray().Select(x=>Id(x.GetString())).ToArray();if(!SameSet(ids,c.Prior))throw new InvalidDataException("Actor prior material set differs from approved asset");string id=Id(c.InitialId);var p=Part(row,id,"Available",false,-1);NewMaterial(l,c,id,1,Matrix(p.GetProperty("actualWorld")));}
    else if(!began)throw new InvalidDataException("Records before unique actor start");
    else if(kind=="actual_cad_feed_created"){string id=Id(detail.GetProperty("id").GetString());int sequence=detail.GetProperty("sequence").GetInt32();if(id==template||sequence!=l.Feeds+2||sequence>20||l.Accepted.Count!=sequence-1)throw new InvalidDataException("One actual initial material plus19new instances only");var offset=detail.GetProperty("offsetMm").EnumerateArray().Select(x=>x.GetDouble()).ToArray();if(offset.Length!=2||offset[0]!=c.Cases[sequence-1].Dx||offset[1]!=c.Cases[sequence-1].Dy||row.GetProperty("state").GetString()!="PartAvailable")throw new InvalidDataException("Recorded feed offset/public readiness mismatch");At(Matrix(row.GetProperty("actualTcpWorld")),c.Ready,c.ReadyMm,c.ReadyDeg,"Actual Ready before new feed");var p=Part(row,id,"Available",false,-1);double[] w=Matrix(detail.GetProperty("actualWorld"));At(w,Matrix(p.GetProperty("actualWorld")),c.WorldMm,c.WorldDeg,"Feed actual matrix readback");NewMaterial(l,c,id,sequence,w);l.Feeds++;}
    else if(kind=="actual_contact_and_attachment_verified"){string id=Id(detail.GetProperty("id").GetString()),contact=detail.GetProperty("contact").GetString();var m=Material(l,id,contact=="C1"?0:contact=="C2"?2:-99);var p=Part(row,id,"Held",true,-1);var before=Matrix(detail.GetProperty("actualBefore"));var after=Matrix(detail.GetProperty("actualAfter"));At(before,after,c.WorldMm,c.WorldDeg,"Actual attachment keep-world");At(after,Matrix(p.GetProperty("actualWorld")),c.WorldMm,c.WorldDeg,"Attached actual part world");m.Stage=contact=="C1"?1:3;if(contact=="C1")l.C1++;else l.C2++;}
    else if(kind=="release_fixture_geometry_verified"){string id=Id(detail.GetProperty("id").GetString());var m=Material(l,id,1);var p=Part(row,id,"AtFixture",false,-1);var before=Matrix(detail.GetProperty("actualBefore"));var after=Matrix(detail.GetProperty("actualAfter"));At(before,after,c.WorldMm,c.WorldDeg,"Fixture detach keep-world");At(after,c.Fixture,c.PlaceMm,c.PlaceDeg,"Actual fixture support");At(after,Matrix(p.GetProperty("actualWorld")),c.WorldMm,c.WorldDeg,"Fixture readback");m.Stage=2;l.FixtureReleases++;}
    else if(kind=="release_box_geometry_verified"){string id=Id(detail.GetProperty("id").GetString());var m=Material(l,id,3);int slot=detail.GetProperty("slot").GetInt32();if(m.Sequence!=l.Accepted.Count+1||slot!=c.Cases[m.Sequence-1].Slot)throw new InvalidDataException("C2 order/recorded box slot mismatch");var p=Part(row,id,"Packed",false,slot);var before=Matrix(detail.GetProperty("actualBefore"));var after=Matrix(detail.GetProperty("actualAfter"));At(before,after,c.WorldMm,c.WorldDeg,"C2 detach keep-world");At(after,c.Slots[slot],c.PlaceMm,c.PlaceDeg,"Actual canonical box placement");At(after,Matrix(p.GetProperty("actualWorld")),c.WorldMm,c.WorldDeg,"C2 actual readback");m.Stage=4;m.Slot=slot;m.World=after;l.Accepted.Add(id);if(detail.GetProperty("cumulativeGeometryPackedCount").GetInt32()!=l.Accepted.Count||detail.GetProperty("activeBoxGeometryPackedCount").GetInt32()!=l.Materials.Values.Count(x=>x.Stage==4))throw new InvalidDataException("C2 actual cumulative/active accounting mismatch");}
    else if(kind=="box_clear_evidence_committed"){if(pendingClear!=null||l.Clears>=4||l.Accepted.Count!=beforeCounts[l.Clears])throw new InvalidDataException("Clear-before1/7/11/17 acceptance boundary mismatch");string proof=detail.GetProperty("path").GetString();if(!Path.IsPathRooted(proof??"")||!Path.GetFullPath(Path.GetDirectoryName(proof)).Equals(Path.GetFullPath(c.LogDirectory),StringComparison.OrdinalIgnoreCase)||Path.GetFileName(proof)!="boxclear_"+c.ActorRun+"_"+(l.Clears+1)+".json")throw new InvalidDataException("Same-run exact owned clearproof required");byte[] proofBytes=Read(proof);if(Hash(proofBytes)!=detail.GetProperty("sha256").GetString())throw new InvalidDataException("Committed clearproof changed");using var pd=JsonDocument.Parse(proofBytes);var pr=pd.RootElement;if(pr.GetProperty("virtualTimeMs").GetDouble()!=time)throw new InvalidDataException("Clearproof time does not match committed event");var items=pr.GetProperty("items").EnumerateArray().ToArray();pendingClear=items.Select(i=>Id(i.GetProperty("id").GetString())).ToList();var packed=l.Materials.Values.Where(m=>m.Stage==4).ToArray();if(items.Length!=sizes[l.Clears]||!SameSet(pendingClear,packed.Select(m=>m.Id)))throw new InvalidDataException("Clearproof exact0/6/4/6 actual ID set mismatch");At(Matrix(row.GetProperty("actualTcpWorld")),c.Ready,c.ReadyMm,c.ReadyDeg,"Actual Ready before clear");foreach(var item in items){var m=Material(l,Id(item.GetProperty("id").GetString()),4);if(item.GetProperty("Sequence").GetInt32()!=m.Sequence||item.GetProperty("Slot").GetInt32()!=m.Slot)throw new InvalidDataException("Clearproof sequence/slot mismatch");var w=Matrix(item.GetProperty("actualWorld"));At(w,c.Slots[m.Slot],c.PlaceMm,c.PlaceDeg,"Clearproof actual support");At(w,m.World,c.WorldMm,c.WorldDeg,"Packed item unchanged before clear");var p=Part(row,m.Id,"Packed",false,m.Slot);At(w,Matrix(p.GetProperty("actualWorld")),c.WorldMm,c.WorldDeg,"Clearproof/log actual matrix");}l.ClearProofPaths.Add(proof);}
    else if(kind=="actual_box_items_removed_from_active_station"){var ids=detail.GetProperty("items").EnumerateArray().Select(v=>Id(v.GetString())).ToArray();if(pendingClear==null||!SameSet(ids,pendingClear))throw new InvalidDataException("Actual archive must follow its committed proof and exact IDs");foreach(string id in ids){Material(l,id,4).Stage=5;l.Archived++;}pendingClear=null;l.Clears++;}
    else if(kind!="signal_edge"&&kind!="step_end"&&kind!="simulation_stop")throw new InvalidDataException("Unknown actor event shape: "+kind);
    if(row.GetProperty("cumulativeGeometryPackedCount").GetInt32()!=l.Accepted.Count||row.GetProperty("activeBoxGeometryPackedCount").GetInt32()!=l.Materials.Values.Count(m=>m.Stage==4)||row.GetProperty("geometryArchivedCount").GetInt32()!=l.Archived)throw new InvalidDataException("Actor event accounting does not equal independent ID ledger");
   }
   if(!began||pendingClear!=null||l.Materials.Count!=20||l.Feeds!=19||l.C1!=20||l.C2!=20||l.FixtureReleases!=20||l.Accepted.Count!=20||l.Accepted.Distinct().Count()!=20||l.Clears!=4||l.Archived!=16||l.Materials.Values.Count(m=>m.Stage==4)!=4||l.Materials.Values.Any(m=>m.Sequence<=16?m.Stage!=5:m.Stage!=4)||l.Materials.ContainsKey(template))throw new InvalidDataException("Independent batch20 material/feed/C1/fixture/C2/clear/archive ledger incomplete");
   l.ReadyReadySeconds=VerifyCsv(Read(csvPath),run,c.Cases);l.SumReadyReadySeconds=l.ReadyReadySeconds.Sum();return l;
  }
  public static double[] VerifyCsv(byte[] bytes,int run,Demo012Case[] cases){using var reader=new StringReader(new UTF8Encoding(false,true).GetString(bytes));if(reader.ReadLine()!="run,cycle,dx_mm,dy_mm,slot,cycle_s,state,stage,err")throw new InvalidDataException("Exact ReadyReady CSV schema required");var seconds=new List<double>();string line;while((line=reader.ReadLine())!=null){if(line.Length==0)continue;var cells=line.Split(',');int i=seconds.Count;if(cells.Length!=9||i>=20||int.Parse(cells[0],Inv)!=run||int.Parse(cells[1],Inv)!=cases[i].Cycle||double.Parse(cells[2],Inv)!=cases[i].Dx||double.Parse(cells[3],Inv)!=cases[i].Dy||int.Parse(cells[4],Inv)!=cases[i].Slot||cells[6]!="MOTION_SEQUENCE_RETURNED"||cells[7]!="50"||cells[8]!="0")throw new InvalidDataException("Unique run/case/recorded offset/slot/error CSV join failed");double t=double.Parse(cells[5],Inv);if(!double.IsFinite(t)||t<=0)throw new InvalidDataException("Positive actual ReadyReady duration required");seconds.Add(t);}if(seconds.Count!=20)throw new InvalidDataException("Exactly20 ReadyReady CSV rows required");return seconds.ToArray();}
 }
}
